package com.logsense.ai;

import com.logsense.rca.RcaResult;

/**
 * Produces a human readable root-cause narrative. Sealed: the platform ships exactly two strategies - a
 * deterministic template (default) and an OpenAI-compatible LLM client (opt-in via {@code logsense.ai.enabled}).
 */
public sealed interface AiSummarizer permits TemplateSummarizer, OpenAiCompatibleSummarizer {

    String summarize(RcaResult result);

    /** {@code true} when the summary is generated by an LLM (stored separately from the deterministic summary). */
    boolean isAiBacked();

    String name();
}
